@page "/apply"
@using sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 1:
                <PersonalInfoStep FullName="@fullName"
                                  Email="@email"
                                  Phone="@phone"
                                  Address="@address"
                                  FullNameChanged="v => fullName = v"
                                  EmailChanged="v => email = v"
                                  PhoneChanged="v => phone = v"
                                  AddressChanged="v => address = v"
                                  OnNext="HandlePersonalInfoNext"
                                  ValidationError="@validationError" />
                break;
            case 2:
                <WorkHistoryStep Entries="workEntries"
                                 OnBack="() => GoToStep(1)"
                                 OnNext="HandleWorkHistoryNext" />
                break;
            case 3:
                <ReferencesStep References="references"
                                OnBack="() => GoToStep(2)"
                                OnNext="HandleReferencesNext" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="coverLetter"
                                 MaxLength="2000"
                                 OnBack="() => GoToStep(3)"
                                 OnNext="HandleCoverLetterNext" />
                break;
            case 5:
                <ReviewStep FullName="@fullName"
                            Email="@email"
                            Phone="@phone"
                            Address="@address"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting"
                            IsSubmitted="isSubmitted"
                            ApplicationId="applicationId"
                            OnEdit="GoToStep"
                            OnSubmit="HandleSubmit" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private string? validationError;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;

    // Step 1
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        if (step < currentStep || completedSteps.Contains(step) || step == currentStep)
        {
            currentStep = step;
            validationError = null;
        }
    }

    private async Task HandlePersonalInfoNext()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(fullName))
        {
            validationError = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(email))
        {
            validationError = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(phone))
        {
            validationError = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(address))
        {
            validationError = "Address is required.";
            return;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(email);
        if (!emailValid)
        {
            validationError = "Please enter a valid email address.";
            return;
        }

        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleWorkHistoryNext()
    {
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleReferencesNext()
    {
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void HandleCoverLetterNext()
    {
        completedSteps.Add(4);
        currentStep = 5;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        StateHasChanged();

        var personal = new PersonalInfo(fullName, email, phone, address);
        var work = new WorkHistory(workEntries.Select(e => new WorkEntry(
            e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
        )).ToList());
        var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, work, refs, coverLetter);

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
        isSubmitted = true;
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

.apply-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2rem;
    padding: 0;
    list-style: none;
    position: relative;
}

.step-indicator::before {
    content: '';
    position: absolute;
    top: 20px;
    left: 10%;
    right: 10%;
    height: 2px;
    background: #e0e0e0;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
}

.step-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #e0e0e0;
    background: white;
    color: #999;
    transition: all 0.3s;
}

.step-item.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: white;
}

.step-item.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: white;
    cursor: pointer;
}

.step-item.completed .step-circle:hover {
    transform: scale(1.1);
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #999;
    max-width: 80px;
}

.step-item.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #2ecc71;
    cursor: pointer;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
}

.step-title {
    font-size: 1.4rem;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 150px;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    gap: 1rem;
}

.btn {
    padding: 0.7rem 1.5rem;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: #4361ee;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #fee;
    color: #e74c3c;
    font-size: 0.85rem;
    padding: 0.4rem 0.8rem;
}

.btn-danger:hover {
    background: #fdd;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Validation */
.validation-error {
    background: #fff0f0;
    border: 1px solid #ffcdd2;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Work Entry Card */
.work-entry-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-card .entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-card .entry-header h4 {
    margin: 0;
    color: #555;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.4rem;
}

.char-count.over-limit {
    color: #e74c3c;
    font-weight: 600;
}

/* Review Section */
.review-section {
    margin-bottom: 1.5rem;
    padding: 1.25rem;
    background: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #e8e8e8;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a2e;
}

.edit-link {
    color: #4361ee;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.edit-link:hover {
    color: #3451d1;
}

.review-field {
    margin-bottom: 0.4rem;
    font-size: 0.9rem;
}

.review-field strong {
    color: #555;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation .checkmark {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.confirmation h2 {
    color: #2ecc71;
    margin-bottom: 0.5rem;
}

.confirmation .app-id {
    font-size: 1.2rem;
    color: #555;
    margin-top: 1rem;
    padding: 0.75rem;
    background: #f0f0f0;
    border-radius: 6px;
    display: inline-block;
}

