.review-section-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a2e;
}

.edit-link {
    color: #4361ee;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.edit-link:hover {
    color: #3451d1;
}

.review-field {
    margin-bottom: 0.4rem;
    font-size: 0.9rem;
}

.review-field strong {
    color: #555;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation .checkmark {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.confirmation h2 {
    color: #2ecc71;
    margin-bottom: 0.5rem;
}

.confirmation .app-id {
    font-size: 1.2rem;
    color: #555;
    margin-top: 1rem;
    padding: 0.75rem;
    background: #f0f0f0;
    border-radius: 6px;
    display: inline-block;
}
