                <label>Company</label>
                <input type="text" value="@entry.Company"
                       @oninput="e => entry.Company = e.Value?.ToString() ?? """ />
            </div>
            <div class="form-group">
                <label>Job Title</label>
                <input type="text" value="@entry.Title"
                       @oninput="e => entry.Title = e.Value?.ToString() ?? """ />
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label>Start Date</label>
                <input type="date" value="@entry.StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => entry.StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd"))" />
            </div>
            <div class="form-group">
