                       disabled="@entry.IsCurrent"
                       @onchange="e => entry.EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!)" />
                <div class="checkbox-group">
                    <input type="checkbox" id="current-@index" checked="@entry.IsCurrent"
                           @onchange="e => entry.IsCurrent = (bool)(e.Value ?? false)" />
                    <label for="current-@index">Currently working here</label>
                </div>
            </div>
        </div>

        <div class="form-group">
            <label>Description</label>
            <textarea rows="3" value="@entry.Description"
                      @oninput="e => entry.Description = e.Value?.ToString() ?? """
                      placeholder="Describe your responsibilities and achievements"></textarea>
        </div>
    </div>
}

<button class="btn btn-secondary" @onclick="AddEntry" style="margin-bottom: 1rem;">
    + Add Another Position
</button>

<div class="step-buttons">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }
}
