toolArgs.file_text:
@namespace sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Components.Pages.Apply

<h2 class="step-title">Personal Information</h2>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="validation-error">@ValidationError</div>
}

<div class="form-group">
    <label for="fullName">Full Name *</label>
    <input id="fullName" type="text" value="@FullName"
           @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")"
           placeholder="Enter your full name" />
</div>

<div class="form-group">
    <label for="email">Email *</label>
    <input id="email" type="email" value="@Email"
           @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")"
           placeholder="you@example.com" />
</div>

<div class="form-group">
    <label for="phone">Phone *</label>
    <input id="phone" type="tel" value="@Phone"
           @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")"
           placeholder="(555) 123-4567" />
</div>

<div class="form-group">
    <label for="address">Address *</label>
    <input id="address" type="text" value="@Address"
           @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")"
           placeholder="123 Main St, City, State" />
</div>

<div class="step-buttons">
    <div></div>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
