@namespace sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Components.Pages.Apply
@using static sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Components.Pages.Apply.Apply

<h2 class="step-title">References</h2>
<p style="color: #666; font-size: 0.9rem; margin-bottom: 1.5rem;">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var reference = References[index];
    <div class="work-entry-card">
        <div class="entry-header">
            <h4>Reference @(index + 1)</h4>
            @if (References.Count > 2)
            {
                <button class="btn btn-danger" @onclick="() => RemoveReference(index)">Remove</button>
            }
        </div>

        <div class="form-row">
            <div class="form-group">
                <label>Name</label>
                <input type="text" value="@reference.Name"
                       @oninput="e => reference.Name = e.Value?.ToString() ?? """ />
            </div>
            <div class="form-group">
                <label>Relationship</label>
                <input type="text" value="@reference.Relationship"
                       @oninput="e => reference.Relationship = e.Value?.ToString() ?? "")"
                       placeholder="e.g., Former Manager" />
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label>Email</label>
                <input type="email" value="@reference.Email"
                       @oninput="e => reference.Email = e.Value?.ToString() ?? """ />
            </div>
            <div class="form-group">
                <label>Phone</label>
                <input type="tel" value="@reference.Phone"
                       @oninput="e => reference.Phone = e.Value?.ToString() ?? """ />
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-secondary" @onclick="AddReference" style="margin-bottom: 1rem;">
