    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }
}

@namespace sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Components.Pages.Apply

<h2 class="step-title">Cover Letter</h2>

<div class="form-group">
    <label for="coverLetter">Write your cover letter</label>
    <textarea id="coverLetter" rows="12"
              value="@CoverLetter"
              @oninput="HandleInput"
              placeholder="Tell us why you'd be a great fit for this role..."></textarea>
    <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
        @CoverLetter.Length / @MaxLength characters
    </div>
</div>

<div class="step-buttons">
    <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next →</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public int MaxLength { get; set; } = 2000;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await CoverLetterChanged.InvokeAsync(value);
    }
}

@namespace sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Components.Pages.Apply
@using static sv_b4ddbb2ea13b4011a1e1c0eec94bcb89.Components.Pages.Apply.Apply

@if (IsSubmitted)
{
    <div class="confirmation">
        <div class="checkmark">✅</div>
        <h2>Application Submitted!</h2>
        <p>Thank you for your application. We'll be in touch soon.</p>
        <div class="app-id">Application ID: <strong>#@ApplicationId</strong></div>
    </div>
}
else
{
    <h2 class="step-title">Review & Submit</h2>

    <div class="review-section">
        <div class="review-section-header">
            <h3>Personal Information</h3>
            <span class="edit-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</span>
        </div>
        <div class="review-field"><strong>Name:</strong> @FullName</div>
        <div class="review-field"><strong>Email:</strong> @Email</div>
        <div class="review-field"><strong>Phone:</strong> @Phone</div>
        <div class="review-field"><strong>Address:</strong> @Address</div>
    </div>

    <div class="review-section">
        <div class="review-section-header">
            <h3>Work History</h3>
            <span class="edit-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</span>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div style="margin-bottom: 0.75rem; padding-bottom: 0.75rem; border-bottom: 1px solid #eee;">
                <div class="review-field"><strong>@entry.Title</strong> at @entry.Company</div>
                <div class="review-field" style="font-size: 0.85rem; color: #666;">
                    @entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </div>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <div class="review-field" style="font-size: 0.85rem; margin-top: 0.25rem;">@entry.Description</div>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-section-header">
            <h3>References</h3>
            <span class="edit-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</span>
        </div>
        @foreach (var r in References)
        {
            <div style="margin-bottom: 0.5rem;">
                <div class="review-field"><strong>@r.Name</strong> (@r.Relationship)</div>
                <div class="review-field" style="font-size: 0.85rem; color: #666;">@r.Email · @r.Phone</div>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="review-section-header">
            <h3>Cover Letter</h3>
            <span class="edit-link" @onclick="() => OnEdit.InvokeAsync(4)">Edit</span>
        </div>
        <div class="review-field" style="white-space: pre-wrap;">@CoverLetter</div>
    </div>

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="() => OnEdit.InvokeAsync(4)">← Back</button>
        <button class="btn btn-primary" @onclick="OnSubmit" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
}

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
}

